import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;

public class TextureGen {
    public static void main\(String[] args\) throws Exception {
        String base = "C:/Users/aaron/Documents/cradlemod/src/main/resources/assets/cradlemod/textures";

        // Item textures - diamond/gem shape
        generateItemTexture\(base + "/item/bloodforged_crystal.png", 0xCC, 0x33, 0x33\);
        generateItemTexture\(base + "/item/steelborn_crystal.png", 0x88, 0x88, 0xAA\);
        generateItemTexture\(base + "/item/raindrop_crystal.png", 0x33, 0x99, 0xFF\);

        // Block textures - cross/crystal shape
        generateBlockTexture\(base + "/block/bloodforged_crystal_block.png", 0xCC, 0x33, 0x33\);
        generateBlockTexture\(base + "/block/steelborn_crystal_block.png", 0x88, 0x88, 0xAA\);
        generateBlockTexture\(base + "/block/raindrop_crystal_block.png", 0x33, 0x99, 0xFF\);

        System.out.println\("All 6 textures generated successfully."\);
    }

    static void generateItemTexture\(String path, int r, int g, int b\) throws Exception {
        BufferedImage img = new BufferedImage\(16, 16, BufferedImage.TYPE_INT_ARGB\);

        // Lighter highlight color
        int rH = Math.min\(255, r + 80\);
        int gH = Math.min\(255, g + 80\);
        int bH = Math.min\(255, b + 80\);

        // Darker shadow color
        int rD = Math.max\(0, r - 50\);
        int gD = Math.max\(0, g - 50\);
        int bD = Math.max\(0, b - 50\);

        int base = \(0xFF << 24\) | \(r << 16\) | \(g << 8\) | b;
        int highlight = \(0xFF << 24\) | \(rH << 16\) | \(gH << 8\) | bH;
        int shadow = \(0xFF << 24\) | \(rD << 16\) | \(gD << 8\) | bD;
        int outline = \(0xFF << 24\) | \(Math.max\(0, r - 80\) << 16\) | \(Math.max\(0, g - 80\) << 8\) | Math.max\(0, b - 80\);

        // Diamond shape: top point at \(7,2\), left at \(3,7\), right at \(12,7\), bottom at \(7,13\)
        // We'll draw it row by row
        // Top half: rows 2-7, expanding from center
        // Bottom half: rows 8-13, contracting to center

        int topY = 2, botY = 13, midY = 7;
        int leftX = 3, rightX = 12, centerX = 7;

        // Draw filled diamond
        for \(int y = topY; y <= botY; y++\) {
            int halfWidth;
            if \(y <= midY\) {
                // Top half - expanding
                halfWidth = \(int\)\(\(double\)\(y - topY\) / \(midY - topY\) * \(centerX - leftX\)\);
            } else {
                // Bottom half - contracting
                halfWidth = \(int\)\(\(double\)\(botY - y\) / \(botY - midY\) * \(rightX - centerX\)\);
            }
            for \(int dx = -halfWidth; dx <= halfWidth; dx++\) {
                int x = centerX + dx;
                if \(x >= 0 && x < 16 && y >= 0 && y < 16\) {
                    // Left side highlight, right side shadow
                    if \(dx < -halfWidth / 2\) {
                        img.setRGB\(x, y, highlight\);
                    } else if \(dx > halfWidth / 2\) {
                        img.setRGB\(x, y, shadow\);
                    } else {
                        img.setRGB\(x, y, base\);
                    }
                }
            }
        }

        // Draw outline edges
        for \(int y = topY; y <= botY; y++\) {
            int halfWidth;
            if \(y <= midY\) {
                halfWidth = \(int\)\(\(double\)\(y - topY\) / \(midY - topY\) * \(centerX - leftX\)\);
            } else {
                halfWidth = \(int\)\(\(double\)\(botY - y\) / \(botY - midY\) * \(rightX - centerX\)\);
            }
            if \(halfWidth >= 0\) {
                int xl = centerX - halfWidth;
                int xr = centerX + halfWidth;
                if \(xl >= 0 && xl < 16\) img.setRGB\(xl, y, outline\);
                if \(xr >= 0 && xr < 16\) img.setRGB\(xr, y, outline\);
            }
        }
        // Top and bottom outline pixels
        if \(topY >= 0 && topY < 16\) img.setRGB\(centerX, topY, outline\);
        if \(botY >= 0 && botY < 16\) img.setRGB\(centerX, botY, outline\);

        // Add a small bright sparkle at top-left area of the gem
        int sparkle = \(0xFF << 24\) | \(Math.min\(255, rH + 60\) << 16\) | \(Math.min\(255, gH + 60\) << 8\) | Math.min\(255, bH + 60\);
        img.setRGB\(6, 4, sparkle\);
        img.setRGB\(7, 4, sparkle\);
        img.setRGB\(6, 5, sparkle\);

        File f = new File\(path\);
        f.getParentFile\(\).mkdirs\(\);
        ImageIO.write\(img, "png", f\);
        System.out.println\("Created: " + path\);
    }

    static void generateBlockTexture\(String path, int r, int g, int b\) throws Exception {
        BufferedImage img = new BufferedImage\(16, 16, BufferedImage.TYPE_INT_ARGB\);

        int rH = Math.min\(255, r + 70\);
        int gH = Math.min\(255, g + 70\);
        int bH = Math.min\(255, b + 70\);

        int rD = Math.max\(0, r - 40\);
        int gD = Math.max\(0, g - 40\);
        int bD = Math.max\(0, b - 40\);

        int base = \(0xFF << 24\) | \(r << 16\) | \(g << 8\) | b;
        int highlight = \(0xFF << 24\) | \(rH << 16\) | \(gH << 8\) | bH;
        int shadow = \(0xFF << 24\) | \(rD << 16\) | \(gD << 8\) | bD;
        int outline = \(0xFF << 24\) | \(Math.max\(0, r - 70\) << 16\) | \(Math.max\(0, g - 70\) << 8\) | Math.max\(0, b - 70\);

        // Crystal cluster / cross pattern for block face
        // Central vertical crystal \(tall, thin\)
        // Plus smaller crystals branching off to the sides

        // Central vertical crystal: x=6-9, y=1-14 \(main tall crystal\)
        drawCrystalShard\(img, 7, 8, 1, 14, 2, base, highlight, shadow, outline\);

        // Left crystal shard: angled, shorter
        drawCrystalShard\(img, 4, 5, 4, 12, 1, base, highlight, shadow, outline\);

        // Right crystal shard: angled, shorter
        drawCrystalShard\(img, 10, 11, 3, 13, 1, shadow, base, shadow, outline\);

        // Small left accent
        drawCrystalShard\(img, 2, 3, 7, 12, 1, highlight, highlight, base, outline\);

        // Small right accent
        drawCrystalShard\(img, 12, 13, 5, 11, 1, shadow, base, shadow, outline\);

        // Add pointed tips to center crystal
        img.setRGB\(7, 0, highlight\);
        img.setRGB\(8, 0, base\);
        img.setRGB\(7, 15, shadow\);
        img.setRGB\(8, 15, shadow\);

        File f = new File\(path\);
        f.getParentFile\(\).mkdirs\(\);
        ImageIO.write\(img, "png", f\);
        System.out.println\("Created: " + path\);
    }

    static void drawCrystalShard\(BufferedImage img, int x1, int x2, int yTop, int yBot,
                                  int tipNarrow, int baseColor, int highlightColor,
                                  int shadowColor, int outlineColor\) {
        int midY = \(yTop + yBot\) / 2;
        for \(int y = yTop; y <= yBot; y++\) {
            // Determine width at this y - widest at middle, narrow at tips
            double progress;
            if \(y <= midY\) {
                progress = \(double\)\(y - yTop\) / Math.max\(1, midY - yTop\);
            } else {
                progress = \(double\)\(yBot - y\) / Math.max\(1, yBot - midY\);
            }

            int startX, endX;
            if \(progress > 0.3\) {
                startX = x1;
                endX = x2;
            } else {
                // Narrow tips
                int mid = \(x1 + x2\) / 2;
                startX = mid;
                endX = mid + \(x2 - x1 > 1 ? 1 : 0\);
            }

            for \(int x = startX; x <= endX; x++\) {
                if \(x >= 0 && x < 16 && y >= 0 && y < 16\) {
                    // Outline on edges
                    if \(x == startX || x == endX || y == yTop || y == yBot\) {
                        img.setRGB\(x, y, outlineColor\);
                    } else if \(x == startX + 1\) {
                        img.setRGB\(x, y, highlightColor\);
                    } else {
                        img.setRGB\(x, y, baseColor\);
                    }
                }
            }
        }
    }
}
JAVAEOF)
